import React from 'react';

import { declOfNum, formatDistance } from '@helpers/formatHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IRouteListItem } from '../@services/routes.service';

interface IRoutesListItemProps {
  data: IRouteListItem;
  onHikingBadgeClick?: (data: IRouteListItem) => void;
}

const RoutesListItem: React.FC<IRoutesListItemProps> = ({ data, onHikingBadgeClick }) => {
  return (
    <PohRow>
      <PohCol sm={8}>
        <div className="d-flex">
          <PohAva colorize={true} src={data.preview} width={48} alt={data.name} className="me-3" />
          <div className="flex-grow-1" style={{ minWidth: 0 }}>
            <h5 className="text-truncate fw-bold mb-0">{data.name}</h5>

            <small className="text-muted">{data.description}</small>
          </div>
        </div>
      </PohCol>
      <PohCol sm={4} className="text-end d-flex d-md-block justify-content-end">
        <div>
          {data.hikingList.length > 0 && (
            <PohBadge
              variant={BadgeVariant.Info}
              title={[...data.hikingList.map((x) => x.name)].join('\n')}
              onClick={(e) => {
                e.stopPropagation();
                onHikingBadgeClick?.(data);
              }}
            >
              {data.hikingList.length}
              &thinsp;
              {declOfNum(data.hikingList.length, ['поход', 'похода', 'походов'])}
            </PohBadge>
          )}
          &nbsp;
          <PohBadge variant={BadgeVariant.Success}>{formatDistance(data.distance)}</PohBadge>
        </div>
        <small className="d-flex align-items-center justify-content-end ms-3" style={{ gap: 4 }}>
          <small style={{ lineHeight: 1 }}>
            <small className="text-muted">Создан:</small>
            <br />
            {data.dateCreate.toLocaleDateString()}
          </small>

          {data.editors.map((editor) => {
            return (
              <PohAva
                key={editor.id}
                src={editor.photo}
                width="1.7em"
                alt={[editor.name, editor.surname].join(' ')}
                title={[editor.name, editor.surname].join(' ')}
                colorize
              />
            );
          })}

          <PohAva
            src={data.author.photo}
            width="2em"
            colorize
            alt={[data.author.name, data.author.surname].join(' ')}
            title={['Создатель:', data.author.name, data.author.surname].join(' ')}
          />
        </small>
      </PohCol>
    </PohRow>
  );
};

export default RoutesListItem;
